import { readFileSync, writeFileSync, mkdirSync } from 'fs'
const src = 'D:/repository/苏住房防汛C端/src/pages/data/ref-assets.ts'
const tmp = 'D:/repository/苏住房防汛C端/.tmp-bug6456'
mkdirSync(tmp, { recursive: true })
const text = readFileSync(src, 'utf8')

// Find each "export const REF_xxx ... = " then scan to matching unescaped closing quote.
const startRe = /export const (REF_\w+)[^=]*=\s*"/g
let m
const out = []
while ((m = startRe.exec(text))) {
  const name = m[1]
  let i = m.index + m[0].length // position right after opening quote
  let body = ''
  while (i < text.length) {
    const c = text[i]
    if (c === '\\') {
      // escaped: keep the escaped char pair as-is (e.g. \" -> ")
      const n = text[i + 1]
      if (n === 'n') body += '\n'
      else if (n === 'r') body += '\r'
      else if (n === 't') body += '\t'
      else body += n
      i += 2
      continue
    }
    if (c === '"') break // unescaped closing quote
    body += c
    i++
  }
  out.push({ name, body })
}

for (const { name, body } of out) {
  writeFileSync(`${tmp}/${name}.html`, body, 'utf8')
  console.log(name, 'len', body.length)
}
console.log('total', out.length)

import { readFileSync, writeFileSync, mkdirSync } from 'fs'
const src = 'D:/repository/苏住房防汛C端/src/pages/data/ref-assets.ts'
const tmp = 'D:/repository/苏住房防汛C端/.tmp-bug6456'
mkdirSync(tmp, { recursive: true })
const text = readFileSync(src, 'utf8')

function scanString(s, start) {
  // start points right after the opening quote
  let i = start, body = ''
  while (i < s.length) {
    const c = s[i]
    if (c === '\\') {
      const n = s[i + 1]
      if (n === 'n') body += '\n'
      else if (n === 'r') body += '\r'
      else if (n === 't') body += '\t'
      else body += n
      i += 2; continue
    }
    if (c === '"') return { body, end: i }
    body += c; i++
  }
  return { body, end: i }
}

const re = /export const (REF_\w+)[^=]*=\s*/g
let m
while ((m = re.exec(text))) {
  const name = m[1]
  let i = m.index + m[0].length
  // skip whitespace
  while (/\s/.test(text[i])) i++
  if (text[i] === '{') {
    // Record object: parse key: "..." pairs
    i++ // past {
    let key = ''
    while (i < text.length) {
      // find next key: "  <word>: "
      const km = /^\s*(\w+)\s*:\s*"/.exec(text.slice(i))
      if (!km) break
      key = km[1]
      const strStart = i + km[0].length - 1 // position of opening quote
      const { body, end } = scanString(text, strStart + 1)
      writeFileSync(`${tmp}/${name}__${key}.html`, body, 'utf8')
      console.log(`${name}__${key}`, body.length)
      i = end + 1
      // skip until next key or closing }
      while (i < text.length && text[i] !== '}' && !/^\s*\w+\s*:\s*"/.test(text.slice(i))) i++
      if (text[i] === '}') break
    }
  } else if (text[i] === '"') {
    const { body } = scanString(text, i + 1)
    writeFileSync(`${tmp}/${name}.html`, body, 'utf8')
    console.log(name, body.length)
  }
}
console.log('done')

